package tesoreria.compras.ordencompra.infrastructure.web.exception;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import tesoreria.compras.ordencompra.domain.exception.OrdenCompraNotFoundException;
@RestControllerAdvice public class OrdenCompraExceptionHandler { @ExceptionHandler(OrdenCompraNotFoundException.class) ProblemDetail notFound(OrdenCompraNotFoundException e){return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(IllegalArgumentException.class) ProblemDetail badRequest(IllegalArgumentException e){return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler(IllegalStateException.class) ProblemDetail conflict(IllegalStateException e){return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT,e.getMessage());} }
